using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using TMPro;
public static class P08ProjectAudit {
 const string W="D:/游戏设计/Codex工作区/work/2026-10-05-P08/checks/";
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static void Assets(){Directory.CreateDirectory(W);var all=AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/")&&!AssetDatabase.IsValidFolder(p)).ToArray();var roots=all.Where(p=>p.EndsWith(".unity")||p.EndsWith(".prefab")||p.Contains("/Resources/")).ToArray();var deps=AssetDatabase.GetDependencies(roots,true).Distinct().OrderBy(x=>x).ToArray();File.WriteAllLines(W+"unity-root-dependencies.txt",deps);var cat=AssetDatabase.LoadAssetAtPath<DemoArtCatalog>("Assets/Resources/DemoArtCatalog.asset");File.WriteAllLines(W+"catalog-current.tsv",cat.entries.Select(e=>e.key+"\t"+(e.sprite?AssetDatabase.GetAssetPath(e.sprite):"MISSING")+"\t"+(e.sprite?e.sprite.rect.ToString():"")));File.WriteAllLines(W+"resource-roots.txt",roots);File.WriteAllText(W+"asset-audit-status.txt",DateTime.Now.ToString("O")+" roots="+roots.Length+" dependencies="+deps.Length+" catalog="+cat.entries.Length+" missingCatalog="+cat.entries.Count(e=>!e.sprite));}
 public static void Runtime(){if(!EditorApplication.isPlaying)throw new Exception("Play required");Directory.CreateDirectory(W);string folder=W+"observed/"+SceneManager.GetActiveScene().name+"_"+DateTime.Now.ToString("HHmmss");Directory.CreateDirectory(folder);var rows=new List<string>{DateTime.Now.ToString("O"),"foreground="+Application.isFocused+" paused="+GamePause.IsPaused+" volume="+AudioListener.volume};foreach(var a in UnityEngine.Object.FindObjectsByType<AudioSource>(FindObjectsInactive.Include))rows.Add("AUDIO "+PathOf(a.transform)+" active="+a.gameObject.activeInHierarchy+" enabled="+a.enabled+" playing="+a.isPlaying+" loop="+a.loop+" clip="+(a.clip?a.clip.name:"none")+" volume="+a.volume);foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Exclude))if(r.enabled&&!r.forceRenderingOff)rows.Add("RENDER "+PathOf(r.transform)+" type="+r.GetType().Name+" bounds="+r.bounds+" scale="+r.transform.lossyScale+" material="+(r.sharedMaterial?r.sharedMaterial.name:"none")+(r is SpriteRenderer s?" sprite="+(s.sprite?s.sprite.name:"none"):""));foreach(var rain in UnityEngine.Object.FindObjectsByType<WindowRainPresentation>(FindObjectsInactive.Exclude))rows.Add("RAIN "+PathOf(rain.transform)+" children="+rain.GetComponentsInChildren<MeshRenderer>().Length);foreach(var t in UnityEngine.Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Exclude))if(t.isActiveAndEnabled&&!string.IsNullOrWhiteSpace(t.text))rows.Add("TEXT "+PathOf(t.transform)+" "+t.text.Replace("\n"," / "));File.WriteAllLines(folder+"/state.txt",rows);}
 public static void ReleaseBuild(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean edit mode required");Directory.CreateDirectory(W+"../build_release");UnityEditor.EditorUtility.UnloadUnusedAssetsImmediate();GC.Collect();var scenes=EditorBuildSettings.scenes.Where(s=>s.enabled).Select(s=>s.path).ToArray();File.WriteAllLines(W+"release-scenes.txt",scenes);var report=UnityEditor.BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=scenes,locationPathName=W+"../build_release/ProjectMystery.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});File.WriteAllText(W+"release-build.txt",DateTime.Now.ToString("O")+" "+report.summary.result+" errors="+report.summary.totalErrors+" warnings="+report.summary.totalWarnings+" bytes="+report.summary.totalSize+" seconds="+report.summary.totalTime.TotalSeconds);File.WriteAllLines(W+"release-build-messages.txt",report.steps.SelectMany(s=>s.messages.Select(m=>s.name+" | "+m.type+" | "+m.content)));if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Release build failed");}
 public static void DevelopmentColdBuild(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean edit mode required");Directory.CreateDirectory(W+"../build_cold");UnityEditor.EditorUtility.UnloadUnusedAssetsImmediate();GC.Collect();var scenes=EditorBuildSettings.scenes.Where(t=>t.enabled).Select(t=>t.path).ToArray();var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=scenes,locationPathName=W+"../build_cold/ProjectMystery.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});File.WriteAllText(W+"cold-build.txt",DateTime.Now.ToString("O")+" "+report.summary.result+" errors="+report.summary.totalErrors+" warnings="+report.summary.totalWarnings+" bytes="+report.summary.totalSize);if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Cold build failed");}
}
